//! Skip-Gram training with negative sampling, hand-rolled and deterministic.
//!
//! The algorithm, in full: for every (center, context) pair generated by a
//! sliding window over the token stream, take one gradient step that raises
//! `σ(u_context · v_center)` and lowers it for `negatives` sampled tokens
//! (unigram^0.75 distribution). Updates touch only the involved rows.
//!
//! Determinism comes from: fixed pair order (no shuffling), a seeded xorshift
//! PRNG for negative samples and initialization, linear lr decay computed
//! from pair progress, and single-threaded f32 accumulation in fixed order.

use crate::learn::model::{LearnerError, SkipGramModel};
use atlas_tokenizer::BpeTokenizer;
use atlas_tokenizer::pretokenize::pretokenize;
use atlas_vocab::Vocab;
use serde::{Deserialize, Serialize};

/// Training hyperparameters. Defaults chosen for Atlas-scale corpora (tens
/// of KB); every field is deterministic input.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TrainerConfig {
    pub dim: usize,
    pub window: usize,
    pub negatives: usize,
    pub lr: f32,
    pub epochs: u32,
    pub seed: u64,
}

impl Default for TrainerConfig {
    fn default() -> Self {
        TrainerConfig {
            dim: 64,
            window: 3,
            negatives: 5,
            lr: 0.05,
            epochs: 40,
            seed: 0,
        }
    }
}

/// Small deterministic PRNG (xorshift64*). No `rand` dependency: training
/// must be reproducible from the seed alone.
pub(crate) struct XorShift(u64);

impl XorShift {
    pub(crate) fn new(seed: u64) -> Self {
        XorShift(seed.max(1))
    }

    pub(crate) fn next_u64(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.0 = x;
        x
    }

    /// Uniform in [0, 1).
    pub(crate) fn next_f32(&mut self) -> f32 {
        (self.next_u64() >> 40) as f32 / (1u64 << 24) as f32
    }

    pub(crate) fn next_range(&mut self, lo: f32, hi: f32) -> f32 {
        lo + (hi - lo) * self.next_f32()
    }
}

fn sigmoid(x: f32) -> f32 {
    // Clamp keeps log-loss finite when |x| grows large during training.
    (1.0 / (1.0 + (-x).exp())).clamp(1e-7, 1.0 - 1e-7)
}

/// Tokenize `text` into vocabulary IDs, growing the vocabulary for unseen
/// tokens. This is the single bridge between text and training: the
/// tokenizer owns splitting and byte tokens, the vocabulary owns IDs.
fn text_to_ids(tokenizer: &BpeTokenizer, vocab: &mut Vocab, text: &str) -> Vec<u32> {
    let mut ids = Vec::new();
    for piece in pretokenize(text) {
        for rank in tokenizer.encode(piece) {
            let bytes = tokenizer
                .token_bytes(rank)
                .expect("encode only emits ranks from this tokenizer");
            ids.push(vocab.get_or_insert(bytes));
        }
    }
    ids
}

/// Adjacent (center, context) pairs within `window` on both sides, in fixed
/// order: centers ascending, contexts left-to-right. Pub(crate) for tests.
pub(crate) fn pairs(ids: &[u32], window: usize) -> Vec<(u32, u32)> {
    let mut out = Vec::new();
    for (i, &center) in ids.iter().enumerate() {
        let lo = i.saturating_sub(window);
        let hi = (i + window + 1).min(ids.len());
        for (j, &context) in ids[lo..hi].iter().enumerate() {
            if lo + j != i {
                out.push((center, context));
            }
        }
    }
    out
}

/// Cumulative unigram^0.75 sampling table over `counts` (one entry per
/// vocabulary ID; zero counts occupy zero width and are never sampled).
struct NegativeSampler {
    cumulative: Vec<f64>,
    total: f64,
}

impl NegativeSampler {
    fn new(counts: &[u64]) -> Self {
        let mut cumulative = Vec::with_capacity(counts.len());
        let mut acc = 0f64;
        for &c in counts {
            acc += (c as f64).powf(0.75);
            cumulative.push(acc);
        }
        NegativeSampler {
            cumulative,
            total: acc,
        }
    }

    fn sample(&self, rng: &mut XorShift) -> usize {
        if self.total <= 0.0 {
            return 0;
        }
        let target = rng.next_f64() * self.total;
        // First index whose cumulative weight exceeds the target: the
        // binary-search form of sampling from the empirical distribution.
        // Zero-weight tokens occupy zero width and can never be first past
        // the target.
        self.cumulative
            .partition_point(|&c| c <= target)
            .min(self.cumulative.len() - 1)
    }
}

impl XorShift {
    fn next_f64(&mut self) -> f64 {
        self.next_f32() as f64
    }
}

/// Train a fresh model over `corpus`, growing `vocab` as needed.
pub fn train(
    vocab: &mut Vocab,
    tokenizer: &BpeTokenizer,
    corpus: &str,
    config: &TrainerConfig,
) -> SkipGramModel {
    let ids = text_to_ids(tokenizer, vocab, corpus);
    let mut model = SkipGramModel::empty(config.dim);
    model.grow_to(vocab.len(), config);
    train_on_stream(
        &mut model,
        &ids,
        token_counts(vocab.len(), &ids),
        config,
        config.lr,
    );
    model
}

impl SkipGramModel {
    /// Incremental learning: tokenize `text` (growing the vocabulary),
    /// append initialized rows for new tokens, then train on the new text
    /// only. The learning rate stays at the decay floor (10% of `lr`) so a
    /// burst of new text does not wreck vectors learned earlier. Without a
    /// replay buffer, older vectors can still drift — that is a documented
    /// limitation, not something to paper over.
    pub fn learn(
        &mut self,
        vocab: &mut Vocab,
        tokenizer: &BpeTokenizer,
        text: &str,
        config: &TrainerConfig,
    ) -> Result<(), LearnerError> {
        if config.dim != self.dim() {
            return Err(LearnerError::Format(format!(
                "config dim {} does not match trained model dim {}",
                config.dim,
                self.dim()
            )));
        }
        let ids = text_to_ids(tokenizer, vocab, text);
        let new_len = vocab.len();
        self.grow_to(new_len, config);
        // Counts only cover the new text; tokens absent from it get zero
        // weight and are never drawn as negatives for this update.
        let counts = token_counts(new_len, &ids);
        let floor_lr = config.lr * 0.1;
        train_on_stream(self, &ids, counts, config, floor_lr);
        Ok(())
    }
}

fn token_counts(vocab_len: usize, ids: &[u32]) -> Vec<u64> {
    let mut counts = vec![0u64; vocab_len];
    for &id in ids {
        counts[id as usize] += 1;
    }
    counts
}

/// The training loop shared by `train` and `learn`.
fn train_on_stream(
    model: &mut SkipGramModel,
    ids: &[u32],
    counts: Vec<u64>,
    config: &TrainerConfig,
    lr_start: f32,
) {
    let all_pairs = pairs(ids, config.window);
    if all_pairs.is_empty() {
        return;
    }
    let dim = model.dim();
    let total_pairs = all_pairs.len() as f32 * config.epochs as f32;
    let mut done = 0f32;
    let mut rng = XorShift::new(config.seed.max(1));
    let sampler = NegativeSampler::new(&counts);
    let mut v_buf = vec![0f32; dim];
    let mut grad = vec![0f32; dim];
    let (w_in, w_out) = model.matrices_mut();

    for _epoch in 0..config.epochs {
        for &(center, context) in &all_pairs {
            let progress = done / total_pairs;
            let lr = lr_start * (1.0 - 0.9 * progress);
            done += 1.0;

            let (c, o) = (center as usize * dim, context as usize * dim);
            v_buf.copy_from_slice(&w_in[c..c + dim]);
            grad.fill(0.0);

            // Positive example: pull center and context together.
            let mut dot = 0f32;
            for j in 0..dim {
                dot += v_buf[j] * w_out[o + j];
            }
            let g = (sigmoid(dot) - 1.0) * lr;
            for j in 0..dim {
                grad[j] += g * w_out[o + j];
                w_out[o + j] -= g * v_buf[j];
            }

            // Negative examples: push center away from sampled tokens.
            for _ in 0..config.negatives {
                let n = sampler.sample(&mut rng) * dim;
                if n == o {
                    continue; // sampled the positive itself; skip cleanly
                }
                let mut ndot = 0f32;
                for j in 0..dim {
                    ndot += v_buf[j] * w_out[n + j];
                }
                let g = sigmoid(ndot) * lr;
                for j in 0..dim {
                    grad[j] += g * w_out[n + j];
                    w_out[n + j] -= g * v_buf[j];
                }
            }

            for j in 0..dim {
                w_in[c + j] -= grad[j];
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn pairs_slide_fixed_window_both_directions() {
        let ids = [10, 20, 30, 40];
        assert_eq!(
            pairs(&ids, 1),
            vec![(10, 20), (20, 10), (20, 30), (30, 20), (30, 40), (40, 30)]
        );
        let wide = pairs(&ids, 2);
        assert!(wide.contains(&(10, 30)));
        assert!(
            !wide.contains(&(10, 40)),
            "window 2 cannot reach distance 3"
        );
    }

    #[test]
    fn negative_sampler_respects_zero_counts() {
        // Token 0 has count 5, token 1 has 0, token 2 has 5.
        let sampler = NegativeSampler::new(&[5, 0, 5]);
        let mut rng = XorShift::new(7);
        for _ in 0..500 {
            assert_ne!(
                sampler.sample(&mut rng),
                1,
                "zero-count must never be sampled"
            );
        }
    }

    #[test]
    fn sigmoid_is_clamped() {
        assert_eq!(sigmoid(-100.0), 1e-7);
        assert_eq!(sigmoid(100.0), 1.0 - 1e-7);
        assert!((sigmoid(0.0) - 0.5).abs() < 1e-6);
    }

    #[test]
    fn xorshift_is_deterministic() {
        let mut a = XorShift::new(42);
        let mut b = XorShift::new(42);
        for _ in 0..100 {
            assert_eq!(a.next_u64(), b.next_u64());
        }
    }

    #[test]
    fn training_is_bit_identical_across_runs() {
        let corpus = "alpha beta gamma alpha beta delta alpha gamma";
        let run = || {
            let tokenizer = test_tokenizer();
            let mut vocab = Vocab::default();
            let config = TrainerConfig {
                dim: 8,
                window: 2,
                negatives: 3,
                lr: 0.1,
                epochs: 10,
                seed: 5,
            };
            train(&mut vocab, &tokenizer, corpus, &config)
        };
        let m1 = run();
        let m2 = run();
        assert_eq!(m1.vocab_len(), m2.vocab_len());
        for id in 0..m1.vocab_len() as u32 {
            assert_eq!(
                m1.token_vector(id),
                m2.token_vector(id),
                "same inputs must produce identical vectors for id {id}"
            );
        }
    }

    fn test_tokenizer() -> BpeTokenizer {
        let path = concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../atlas-tokenizer/tests/fixtures/cl100k.tiktoken"
        );
        let f = std::fs::File::open(path).expect("ranks fixture");
        BpeTokenizer::from_tiktoken_reader(std::io::BufReader::new(f)).expect("parses")
    }
}
